# Generated by build.py from recipe.yml for recipe mqtt-move-a-device-to-mqtt5. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--mqtt5-disconnect-after-retained', '--topic', '"plant/#;retain"', 'mqtt://127.0.0.1:8080/', 'mqtt5://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -d 68 mqtt://127.0.0.1:8080/plant/hall/temp --next -s mqtt5://127.0.0.1:8081/plant/hall/temp } finally { Stop-Process $server0 }
